from html.parser import HTMLParser
from pathlib import Path
from hashlib import sha256
import json, re

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1
    def handle_data(self, data):
        if not self.hidden and data.strip():
            self.parts.append(' '.join(data.split()))

root = Path('products/services/nz-gets-offline-delivery')
source = root / 'raw/healthnz-35365145.html'
raw = source.read_bytes()
parser = VisibleText()
parser.feed(raw.decode('utf-8', errors='replace'))
pattern = re.compile(r'closing|deadline|wayfinding|pathfinding|supplier|scope|deliverable|separate|subcontract|submission|payment|registration|lot\b|proposal', re.I)
indices = sorted({j for i, part in enumerate(parser.parts) if pattern.search(part) for j in range(max(0, i-1), min(len(parser.parts), i+2))})
result = {'url': 'https://www.gets.govt.nz/HEALTHNZ/ExternalTenderDetails.htm?id=35365145', 'source_sha256': sha256(raw).hexdigest(), 'method': 'Static HTML text extraction with whitespace normalization. Check the original notice before qualifying scope or quoting.', 'excerpts': [{'position': i, 'text': parser.parts[i]} for i in indices]}
out = root / 'healthnz-original-scope-extract.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'source_sha256': result['source_sha256'], 'excerpts': len(indices)}))
